      readRequestAuthority: ({ requestId, actor }) => sbRpc(env, 'timesheet_correction_request_authority_v1', {
        p_request_id: requestId, p_actor_user_id: actor.actor_user_id
      }, { timeoutMs: 12000 })
    });
