      status: 200, headers: { ...JSON_HEADERS, 'cache-control': 'no-store', 'x-content-type-options': 'nosniff' }
    }));
  } catch (error) { return withCORS(env, req, timesheetCorrectionOfficeFailure(error)); }
}

